const body = $input.first().json.body ?? $input.first().json;
const chatId = body.chatId ?? 0;
const userId = body.userId ?? 0;
const messageType = body.messageType ?? 'text';
const content = body.content ?? '';
const fileId = body.fileId ?? null;
const fragmentCount = body.fragmentCount ?? 1;
return [{ json: { chatId, userId, messageType, content, fileId, fragmentCount } }];

const inp = $('Normalizar Input Router').first().json;
const chatId = inp.chatId;
const userId = inp.userId;
const messageType = inp.messageType;
const raw = String(inp.content || '');
const content = raw.toLowerCase().trim();
const fileId = inp.fileId;
const fragmentCount = inp.fragmentCount;
const dbUserId = $input.first().json.db_user_id;

let intention = 'default';
let reminderTitle = '', reminderDatetime = null, reminderDateFormatted = '';
let calTitle = '', calStartDatetime = null, calEndDatetime = null, calQueryRange = 'today';
let responseMessage = '';

const R_REMINDER = /recue?rdame?|recordar|avísame|avisame|en \d+ (minutos?|horas?)|ma[nñ]ana a las?|hoy a las?/i;
const R_QUERY = /qu[eé] tengo(?! en el (calendario|agenda))|mis recordatorios|para hoy|para ma[nñ]ana(?! en el)|esta semana|pr[oó]ximos?/i;
const R_CAL_CREATE = /crea(?:r)? (?:una? )?(?:reuni[oó]n|evento|cita)|agenda(?:r)? (?:una? )?(?:reuni[oó]n|evento|cita)|programa(?:r)? (?:una? )?(?:cita|reuni[oó]n)|pon(?:er)? en (?:el )?calendario|a[nñ]ade al calendario/i;
const R_CAL_QUERY = /(?:mis )?eventos(?: de| del)?|calendario(?: de)? (?:hoy|ma[nñ]ana|esta semana)|qu[eé] tengo en (?:el )?(?:calendario|agenda)|reuniones(?: de hoy| de ma[nñ]ana)?/i;

function parseDate(text) {
  const now = new Date(); let m;
  m = text.match(/en (\d+) minutos?/); if (m) return new Date(now.getTime() + parseInt(m[1]) * 60000);
  m = text.match(/en (\d+) horas?/); if (m) return new Date(now.getTime() + parseInt(m[1]) * 3600000);
  m = text.match(/ma[nñ]ana a las? (\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i);
  if (m) { const d = new Date(now); d.setDate(d.getDate()+1); let h=parseInt(m[1]); const min=m[2]?parseInt(m[2]):0; if(m[3]==='pm'&&h<12)h+=12; d.setHours(h,min,0,0); return d; }
  m = text.match(/hoy a las? (\d{1,2})(?::(\d{2}))?\s*(am|pm)?/i);
  if (m) { const d = new Date(now); let h=parseInt(m[1]); const min=m[2]?parseInt(m[2]):0; if(m[3]==='pm'&&h<12)h+=12; d.setHours(h,min,0,0); return d; }
  return null;
}

if (messageType === 'photo' && content === '__foto_sin_contexto__') {
  intention = 'foto_sin_contexto';
  responseMessage = '\u{1F4F8} Recibí tu imagen. ¿Qué quieres que haga con ella?';
} else if (R_CAL_CREATE.test(content)) {
  calTitle = raw.replace(/crea(?:r)? (?:una? )?(?:reuni[oó]n|evento|cita)|agenda(?:r)? (?:una? )?(?:reuni[oó]n|evento|cita)|programa(?:r)? (?:una? )?(?:cita|reuni[oó]n)|pon(?:er)? en (?:el )?calendario|a[nñ]ade al calendario/gi,'').replace(/\s+/g,' ').trim();
  if (calTitle.length < 3) calTitle = raw;
  const pd = parseDate(content);
  if (pd && !isNaN(pd.getTime())) {
    intention = 'calendario_crear';
    calStartDatetime = pd.toISOString();
    calEndDatetime = new Date(pd.getTime() + 3600000).toISOString();
    responseMessage = '\u{1F4C5} Creando evento en tu Google Calendar...';
  } else {
    intention = 'default';
    responseMessage = '\u2753 No entendí la fecha del evento.\n\u2022 "Crea una reunión mañana a las 3pm"\n\u2022 "Agenda una cita hoy a las 10am"';
  }
} else if (R_CAL_QUERY.test(content)) {
  intention = 'calendario_consulta';
  if (/ma[nñ]ana/.test(content)) calQueryRange = 'tomorrow';
  else if (/semana|próximos|proximos/.test(content)) calQueryRange = 'week';
  else calQueryRange = 'today';
} else if (R_REMINDER.test(content)) {
  reminderTitle = raw.replace(/recue?rdame?|recordar|avísame|avisame/gi,'').replace(/\s+/g,' ').trim();
  if (reminderTitle.length < 3) reminderTitle = raw;
  const pd = parseDate(content);
  if (pd && !isNaN(pd.getTime())) {
    intention = 'recordatorio';
    reminderDatetime = pd.toISOString();
    try { reminderDateFormatted = pd.toLocaleString('es-CO',{timeZone:'America/Bogota',weekday:'short',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}); } catch(e) { reminderDateFormatted = pd.toISOString(); }
    responseMessage = '\u2705 Listo! Te recuerdo el ' + reminderDateFormatted + ':\n_("' + reminderTitle.substring(0,100) + '")_';
  } else {
    intention = 'default';
    responseMessage = '\u2753 No entendí la fecha.\n\u2022 "en 10 minutos"\n\u2022 "mañana a las 3pm"\n\u2022 "hoy a las 8am"';
  }
} else if (R_QUERY.test(content)) {
  intention = 'consulta';
} else {
  intention = 'default';
  responseMessage = '\u{1F44B} Estoy aquí para ayudarte.\n\n\u2022 *Recordatorio*: "Recuérdame ir al gym mañana a las 7am"\n\u2022 *Agenda*: "¿Qué tengo para hoy?"\n\u2022 *Calendario*: "¿Mis eventos de hoy?"\n\u2022 *Crear evento*: "Crea una reunión mañana a las 3pm"';
}

return [{ json: { chatId, userId, dbUserId, messageType, content, fileId, fragmentCount, intention, reminderTitle, reminderDatetime, reminderDateFormatted, calTitle, calStartDatetime, calEndDatetime, calQueryRange, responseMessage } }];

const items = $input.all();
const chatId = $('Clasificar Intencion').first().json.chatId;
let msg;
if (!items.length || !items[0].json.title) {
  msg = '\u{1F4CB} *No tienes recordatorios pendientes.*\n\nEscribe "Recuérdame..." para crear uno.';
} else {
  const lines = items.map(function(i) { const d = new Date(i.json.remind_at); let ds; try { ds = d.toLocaleString('es-CO',{timeZone:'America/Bogota',weekday:'short',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}); } catch(e){ds=i.json.remind_at;} return '\u2022 ' + ds + ' \u2014 ' + (i.json.title||'Sin título'); });
  msg = '\u{1F4CB} *Tus próximos recordatorios:*\n' + lines.join('\n');
}
return [{ json: { chatId, responseMessage: msg } }];

